-- Generated by scripts/bundle-release-1.mjs from cloud/portal/supabase/migrations; do not edit by hand.
-- Safe to run once: if it was already applied, it stops at the first statement and changes nothing.
-- Before: the backup schema backup_20261108 already holds a copy of every existing table (2026-11-08).
-- After: run the checks at the end; the rollback is cloud/portal/supabase/rollback/release-1.sql.
begin;
do $$ begin
  if exists (select 1 from supabase_migrations.schema_migrations where version = '20261104000000') then
    raise exception 'Release 1 migrations are already applied: nothing to do';
  end if;
end $$;

-- ===== 20261104000000_portal_url_sites.sql =====
-- Sites connected by address only (D25): no repository, no GitHub Actions. pg_cron wakes the `scan` Edge Function every
-- 10 minutes; it claims due sites, crawls them from Supabase and stores a snapshot. Adding a site or pressing "Scan now"
-- wakes it at once. Needs the pg_cron and pg_net extensions, and two Vault secrets set once per project:
--   select vault.create_secret('https://<ref>.supabase.co/functions/v1/scan', 'scan_url');
--   select vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'scan_secret');
create extension if not exists pg_net;
create extension if not exists pg_cron;

alter table public.sites
  add column mode text not null default 'github' check (mode in ('github', 'url')),
  add column next_scan_at timestamptz,
  add column scan_state text check (scan_state in ('queued', 'running', 'done', 'failed')),
  add column scan_started_at timestamptz,
  add column scan_error text;
alter table public.sites drop constraint sites_status_check;
alter table public.sites add constraint sites_status_check check (status in ('connecting', 'scanning', 'live', 'paused'));
create index sites_scan_due_idx on public.sites (next_scan_at) where mode = 'url';

-- Wake the scan function. Never fails the caller: without pg_net or the Vault secrets the 10-minute schedule still runs.
create or replace function private.kick_scan()
returns void language plpgsql security definer set search_path = '' as $$
declare v_url text; v_secret text;
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'scan_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'scan_secret';
  if v_url is null or v_secret is null then return; end if;
  perform net.http_post(url := v_url, headers := jsonb_build_object('Content-Type', 'application/json', 'x-scan-secret', v_secret), body := '{}'::jsonb, timeout_milliseconds := 2000);
exception when others then null;
end;
$$;

-- Hosts the scanner refuses: bare IPs, localhost and private suffixes (the scanner runs inside the provider's network).
create or replace function private.public_host(p_url text)
returns boolean language sql immutable set search_path = '' as $$
  select p_url ~ '^https://[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+(:443)?(/[^\s]*)?$'
     and substring(p_url from '^https://([^/:]+)') !~ '(^localhost$|\.local$|\.internal$|\.localhost$|^[0-9.]+$)';
$$;

-- Address-only sites must keep a public address even when a member edits the url column directly (members may update
-- name, url, repo and status; see the first migration), so the rule lives in the table, not only in add_site_by_url.
alter table public.sites add constraint sites_url_public check (mode <> 'url' or private.public_host(url));

create or replace function public.add_site_by_url(p_url text, p_name text default null, p_org uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_site public.sites; v_raw text := trim(coalesce(p_url, '')); v_url text; v_name text;
begin
  -- Lower-case the scheme and host only; paths can be case-sensitive.
  if v_raw !~* '^https://[^/\s]+' then raise exception 'use the public https:// address of the website'; end if;
  v_url := 'https://' || lower(substring(v_raw from '(?i)^https://([^/]+)')) || coalesce(substring(v_raw from '(?i)^https://[^/]+(/.*)$'), '');
  if (select auth.uid()) is null then raise exception 'sign in first'; end if;
  v_org := coalesce(p_org, (select m.org_id from public.org_members m where m.user_id = (select auth.uid()) order by m.created_at limit 1));
  if v_org is null or not private.is_member(v_org) then raise exception 'not a member of that org'; end if;
  if v_url !~ '/$' and v_url !~ '^https://[^/]+/.+' then v_url := v_url || '/'; end if;
  if not private.public_host(v_url) then raise exception 'use the public https:// address of the website'; end if;
  if (select count(*) from public.sites where org_id = v_org and mode = 'url') >= 50 then raise exception 'this workspace already has 50 websites connected by address'; end if;
  if (select count(*) from public.sites where org_id = v_org and mode = 'url' and created_at > now() - interval '1 day') >= 20 then raise exception 'at most 20 websites can be added by address per day'; end if;
  if exists (select 1 from public.sites where org_id = v_org and url = v_url) then raise exception 'that website is already in this workspace'; end if;
  v_name := coalesce(nullif(trim(coalesce(p_name, '')), ''), regexp_replace(substring(v_url from '^https://([^/:]+)'), '^www\.', ''));
  insert into public.sites (org_id, name, url, mode, status, next_scan_at, scan_state)
    values (v_org, left(v_name, 120), v_url, 'url', 'scanning', now(), 'queued') returning * into v_site;
  perform private.kick_scan();
  return to_jsonb(v_site);
end;
$$;

-- Ask for a fresh scan of a site connected by address. At most one every 30 minutes.
create or replace function public.scan_now(p_site uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v public.sites;
begin
  select * into v from public.sites where id = p_site;
  if v.id is null or not private.is_member(v.org_id) then raise exception 'not found'; end if;
  if v.mode <> 'url' then raise exception 'this website reports from its own repository; run its seo-daily workflow instead'; end if;
  if v.scan_state in ('queued', 'running') and coalesce(v.scan_started_at, now()) > now() - interval '15 minutes' then return jsonb_build_object('ok', true, 'state', v.scan_state); end if;
  if v.last_snapshot_at > now() - interval '30 minutes' then raise exception 'scanned less than 30 minutes ago'; end if;
  update public.sites set next_scan_at = now(), scan_state = 'queued', scan_error = null where id = p_site;
  perform private.kick_scan();
  return jsonb_build_object('ok', true, 'state', 'queued');
end;
$$;

-- For the scan function (service role): the shared secret check, claiming the next due site, and storing the result.
create or replace function public.scan_secret_ok(p_secret text)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from vault.decrypted_secrets where name = 'scan_secret' and decrypted_secret = p_secret);
$$;

create or replace function public.claim_scan()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v public.sites;
begin
  update public.sites s set scan_state = 'running', scan_started_at = now()
  where s.id = (select x.id from public.sites x
                where x.mode = 'url' and x.status <> 'paused' and x.next_scan_at <= now()
                  and (x.scan_state is distinct from 'running' or x.scan_started_at < now() - interval '15 minutes')
                order by x.next_scan_at limit 1 for update skip locked)
  returning s.* into v;
  return case when v.id is null then null else jsonb_build_object('id', v.id, 'name', v.name, 'url', v.url) end;
end;
$$;

create or replace function public.finish_scan(p_site uuid, p_data jsonb default null, p_error text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_at timestamptz := now();
begin
  if p_error is not null or p_data is null or jsonb_typeof(p_data) <> 'object' then
    update public.sites set scan_state = 'failed', scan_error = left(coalesce(p_error, 'no data'), 300), next_scan_at = v_at + interval '6 hours' where id = p_site;
    return jsonb_build_object('ok', false);
  end if;
  if pg_column_size(p_data) > 4 * 1024 * 1024 then
    update public.sites set scan_state = 'failed', scan_error = 'snapshot larger than 4 MB', next_scan_at = v_at + interval '1 day' where id = p_site;
    return jsonb_build_object('ok', false);
  end if;
  insert into public.site_snapshots (site_id, taken_at, data) values (p_site, v_at, p_data);
  update public.sites set status = case when status = 'paused' then status else 'live' end, last_snapshot_at = v_at,
    scan_state = 'done', scan_error = null, next_scan_at = v_at + interval '1 day' where id = p_site;
  delete from public.site_snapshots where site_id = p_site and id not in (select id from public.site_snapshots where site_id = p_site order by taken_at desc limit 120);
  return jsonb_build_object('ok', true, 'at', v_at);
end;
$$;

revoke all on function private.kick_scan(), public.add_site_by_url(text, text, uuid), public.scan_now(uuid), public.scan_secret_ok(text),
  public.claim_scan(), public.finish_scan(uuid, jsonb, text) from public, anon, authenticated;
grant execute on function public.add_site_by_url(text, text, uuid), public.scan_now(uuid) to authenticated;
grant execute on function public.scan_secret_ok(text), public.claim_scan(), public.finish_scan(uuid, jsonb, text) to service_role;

-- Every 10 minutes: the function scans whatever is due (sites are due once a day).
-- (pg_cron schedule not created: Cloudflare is the only scheduler, D30)

insert into supabase_migrations.schema_migrations (version, name) values ('20261104000000', 'portal_url_sites');

-- ===== 20261108000000_r1_contracts.sql =====
-- Release 1 shared contracts (docs/product/R1-CONTRACTS.md): clients under an agency, client accounts limited to results
-- and submissions, jobs with a guarded lifecycle and an append-only event log, independent reviews, agency-only
-- approvals, untrusted client submissions, private site memory, integration records without secrets, and an audit log.
-- Additive: existing tables, functions and the portal keep working. Not applied anywhere until the owner approves.

-- Clients of an agency, and the client's people (viewers). A client viewer is never an agency member. ------------------
create table public.clients (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.orgs (id) on delete cascade,
  name text not null check (length(name) between 1 and 120),
  created_at timestamptz not null default now()
);
create index clients_org_idx on public.clients (org_id);
alter table public.sites add column client_id uuid references public.clients (id) on delete set null;
create index sites_client_idx on public.sites (client_id);

create table public.client_members (
  client_id uuid not null references public.clients (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (client_id, user_id)
);
create index client_members_user_idx on public.client_members (user_id);

create table public.client_invites (
  id bigserial primary key,
  client_id uuid not null references public.clients (id) on delete cascade,
  email text not null check (email = lower(email) and email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  invited_by uuid references auth.users (id) on delete set null,
  accepted_at timestamptz,
  created_at timestamptz not null default now(),
  unique (client_id, email)
);

-- A site's client must belong to the site's agency.
create or replace function private.client_org(p_client uuid)
returns uuid language sql stable security definer set search_path = '' as $$ select c.org_id from public.clients c where c.id = p_client $$;
-- Same-org rules are triggers (security definer), not CHECK constraints: a CHECK calling a private function would need
-- every writing role (including members renaming a site) to have execute rights on it.
create or replace function private.sites_client_same_org() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.client_id is not null and private.client_org(new.client_id) is distinct from new.org_id then raise exception 'client belongs to another agency'; end if;
  return new;
end; $$;
create trigger sites_client_same_org before insert or update of client_id, org_id on public.sites for each row execute function private.sites_client_same_org();
create or replace function private.row_same_org() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if private.site_org(new.site_id) is distinct from new.org_id then raise exception 'site belongs to another agency'; end if;
  return new;
end; $$;

-- Agency authority: an agency (org) member. Client viewers are never org members, so every agency-only check below holds.
create or replace function private.is_client_viewer(p_site uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.sites s join public.client_members m on m.client_id = s.client_id
                 where s.id = p_site and m.user_id = (select auth.uid()));
$$;
create or replace function private.is_agency_for_site(p_site uuid)
returns boolean language sql stable security definer set search_path = '' as $$ select private.is_member(private.site_org(p_site)) $$;

-- New users: a pending client invitation makes the person a client viewer and no agency org is created for them.
create or replace function private.on_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_org uuid;
begin
  if exists (select 1 from public.client_invites i where i.email = lower(new.email) and i.accepted_at is null) then
    insert into public.client_members (client_id, user_id) select i.client_id, new.id from public.client_invites i
      where i.email = lower(new.email) and i.accepted_at is null on conflict do nothing;
    update public.client_invites set accepted_at = now() where email = lower(new.email) and accepted_at is null;
    return new;
  end if;
  if exists (select 1 from public.invites i where i.email = lower(new.email) and i.accepted_at is null) then return new; end if; -- joins an agency through accept_invites
  insert into public.orgs (name) values (coalesce(nullif(split_part(new.email, '@', 1), ''), 'My agency')) returning id into v_org;
  insert into public.org_members (org_id, user_id, role) values (v_org, new.id, 'owner');
  return new;
end;
$$;

-- Jobs: one record per unit of work, with the lifecycle from the master spec (§3). ------------------------------------
create table public.jobs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.orgs (id) on delete cascade,
  site_id uuid not null references public.sites (id) on delete cascade,
  kind text not null check (length(kind) between 1 and 80),
  title text not null check (length(title) between 1 and 200),
  objective text,
  source text not null check (source in ('schedule', 'event', 'on_demand', 'seo_god', 'agency', 'client_submission')),
  priority int not null default 3 check (priority between 1 and 5), -- 1 owner request, 2 critical maintenance, 3+ opportunities
  risk text not null default 'low' check (risk in ('low', 'medium', 'high')),
  requires_approval boolean not null default false,
  status text not null default 'proposed' check (status in ('proposed', 'scoped', 'queued', 'running', 'awaiting_review', 'awaiting_approval', 'authorized', 'deploying', 'verifying', 'completed', 'failed', 'cancelled', 'rejected', 'escalated')),
  idempotency_key text,
  depends_on uuid[] not null default '{}',
  agent text, agent_version text,
  inputs jsonb not null default '{}', outputs jsonb, evidence jsonb,
  attempts int not null default 0, max_attempts int not null default 3 check (max_attempts between 1 and 10),
  budget_usd numeric(10, 4) not null default 0 check (budget_usd >= 0), cost_usd numeric(10, 4) not null default 0,
  lease_owner text, lease_until timestamptz, not_before timestamptz,
  error text, deployment_ref text, rollback_ref text,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  constraint jobs_high_risk_needs_approval check (risk <> 'high' or requires_approval),
  constraint jobs_client_submissions_need_approval check (source <> 'client_submission' or requires_approval)
);
create unique index jobs_idempotency_idx on public.jobs (site_id, idempotency_key) where idempotency_key is not null;
create index jobs_site_status_idx on public.jobs (site_id, status);
create index jobs_queue_idx on public.jobs (priority, created_at) where status = 'queued';

create table public.job_events (
  id bigserial primary key,
  job_id uuid not null references public.jobs (id) on delete cascade,
  org_id uuid not null,
  at timestamptz not null default now(),
  actor_kind text not null check (actor_kind in ('user', 'agent', 'system')),
  actor text,
  from_status text, to_status text,
  note text, data jsonb
);
create index job_events_job_idx on public.job_events (job_id, at);

create table public.reviews (
  id bigserial primary key,
  job_id uuid not null references public.jobs (id) on delete cascade,
  org_id uuid not null,
  reviewer text not null, producer text not null,
  verdict text not null check (verdict in ('pass', 'fail', 'needs_changes')),
  rationale text, evidence jsonb,
  created_at timestamptz not null default now(),
  constraint reviews_independent check (reviewer <> producer)
);

create table public.approvals (
  id bigserial primary key,
  job_id uuid not null references public.jobs (id) on delete cascade,
  org_id uuid not null,
  decided_by uuid not null references auth.users (id),
  decision text not null check (decision in ('approve', 'reject', 'request_changes')),
  note text,
  created_at timestamptz not null default now()
);

-- Allowed lifecycle moves. src/core/job-lifecycle.mjs holds the same table; test/job-lifecycle.test.mjs checks they match.
create or replace function private.job_move_allowed(p_from text, p_to text)
returns boolean language sql immutable set search_path = '' as $$
  select (p_from, p_to) in (
    ('proposed','scoped'), ('proposed','cancelled'), ('proposed','rejected'),
    ('scoped','queued'), ('scoped','awaiting_approval'), ('scoped','cancelled'),
    ('queued','running'), ('queued','cancelled'),
    ('running','awaiting_review'), ('running','completed'), ('running','failed'),
    ('awaiting_review','awaiting_approval'), ('awaiting_review','authorized'), ('awaiting_review','queued'), ('awaiting_review','failed'),
    ('awaiting_approval','authorized'), ('awaiting_approval','rejected'), ('awaiting_approval','scoped'),
    ('authorized','queued'), ('authorized','deploying'), ('authorized','completed'),
    ('deploying','verifying'), ('deploying','failed'),
    ('verifying','completed'), ('verifying','failed'),
    ('failed','queued'), ('failed','escalated'),
    ('escalated','queued'), ('escalated','cancelled')
  );
$$;

-- The single gate every status change passes: legal move, approval before anything runs or deploys when one is required,
-- a passing independent review before approval or deploy for non-low risk, retry cap, and an event row.
create or replace function private.move_job(p_job uuid, p_to text, p_actor_kind text, p_actor text, p_note text default null, p_data jsonb default null)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs; v_from text; approved boolean; reviewed boolean;
begin
  select * into j from public.jobs where id = p_job for update;
  if j.id is null then raise exception 'job not found'; end if;
  v_from := j.status;
  if not private.job_move_allowed(v_from, p_to) then raise exception 'job cannot move from % to %', v_from, p_to; end if;
  approved := coalesce((select a.decision = 'approve' from public.approvals a where a.job_id = j.id order by a.id desc limit 1), false);
  reviewed := coalesce((select r.verdict = 'pass' from public.reviews r where r.job_id = j.id order by r.id desc limit 1), false);
  -- Nothing that needs approval is queued, run, authorized or deployed without the latest agency decision being "approve".
  if j.requires_approval and p_to in ('queued', 'running', 'authorized', 'deploying') and not approved then raise exception 'job needs agency approval first'; end if;
  -- Medium and high risk work leaves review only with a passing independent review.
  if v_from = 'awaiting_review' and p_to in ('awaiting_approval', 'authorized') and j.risk <> 'low' and not reviewed then raise exception 'job needs a passing independent review'; end if;
  if v_from = 'running' and p_to = 'completed' and (j.risk <> 'low' or j.requires_approval) then raise exception 'only low-risk jobs without approval can complete straight from running'; end if;
  if v_from in ('failed', 'escalated') and p_to = 'queued' and v_from = 'failed' and j.attempts >= j.max_attempts then raise exception 'retry cap reached: escalate'; end if;
  update public.jobs set status = p_to, updated_at = now(),
    attempts = attempts + case when p_to = 'running' then 1 else 0 end,
    lease_owner = case when p_to = 'running' then lease_owner end,
    lease_until = case when p_to = 'running' then lease_until end
    where id = j.id returning * into j;
  insert into public.job_events (job_id, org_id, actor_kind, actor, from_status, to_status, note, data) values (j.id, j.org_id, p_actor_kind, p_actor, v_from, p_to, p_note, p_data);
  return j;
end;
$$;

-- Agency staff create work; the service role (SEO God, workers) does too. High risk always needs approval.
create or replace function public.create_job(p_site uuid, p_kind text, p_title text, p_source text default 'agency', p_risk text default 'low',
  p_requires_approval boolean default false, p_priority int default 3, p_inputs jsonb default '{}', p_idempotency_key text default null,
  p_objective text default null, p_depends_on uuid[] default '{}', p_budget_usd numeric default 0)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs; v_org uuid := private.site_org(p_site); is_service boolean := (select auth.role()) = 'service_role';
begin
  if v_org is null then raise exception 'site not found'; end if;
  if not is_service and not private.is_member(v_org) then raise exception 'not allowed'; end if;
  if not is_service and p_source not in ('agency', 'on_demand') then raise exception 'agency staff create agency or on-demand jobs'; end if;
  if p_idempotency_key is not null then
    select * into j from public.jobs where site_id = p_site and idempotency_key = p_idempotency_key;
    if j.id is not null then return j; end if; -- a repeated event does not create a second job
  end if;
  insert into public.jobs (org_id, site_id, kind, title, objective, source, priority, risk, requires_approval, inputs, idempotency_key, depends_on, budget_usd, created_by)
    values (v_org, p_site, p_kind, p_title, p_objective, p_source, coalesce(p_priority, 3), p_risk, p_requires_approval or p_risk = 'high' or p_source = 'client_submission',
            coalesce(p_inputs, '{}'), p_idempotency_key, coalesce(p_depends_on, '{}'), coalesce(p_budget_usd, 0), (select auth.uid()))
    returning * into j;
  insert into public.job_events (job_id, org_id, actor_kind, actor, to_status, note) values (j.id, j.org_id, case when is_service then 'agent' else 'user' end, coalesce((select auth.uid())::text, 'service'), 'proposed', 'created');
  insert into public.audit_log (org_id, site_id, actor, action, target) values (j.org_id, j.site_id, (select auth.uid()), 'job.create', j.id::text);
  return j;
end;
$$;

-- Agency-only decisions on a job waiting for approval.
create or replace function public.approve_job(p_job uuid, p_decision text, p_note text default null)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs;
begin
  select * into j from public.jobs where id = p_job;
  if j.id is null or not private.is_member(j.org_id) then raise exception 'not allowed'; end if;
  if j.status <> 'awaiting_approval' then raise exception 'job is not waiting for approval'; end if;
  if p_decision not in ('approve', 'reject', 'request_changes') then raise exception 'decision must be approve, reject or request_changes'; end if;
  insert into public.approvals (job_id, org_id, decided_by, decision, note) values (j.id, j.org_id, (select auth.uid()), p_decision, nullif(trim(coalesce(p_note, '')), ''));
  insert into public.audit_log (org_id, site_id, actor, action, target, data) values (j.org_id, j.site_id, (select auth.uid()), 'job.' || p_decision, j.id::text, jsonb_build_object('note', p_note));
  return private.move_job(j.id, case p_decision when 'approve' then 'authorized' when 'reject' then 'rejected' else 'scoped' end, 'user', (select auth.uid())::text, p_note);
end;
$$;

-- Workers (service role): move, review, claim with a lease, fail with a retry cap.
create or replace function public.transition_job(p_job uuid, p_to text, p_actor text, p_note text default null, p_data jsonb default null)
returns public.jobs language plpgsql security definer set search_path = '' as $$
begin
  -- Rejecting, and authorizing work that needs approval, belong to the agency (approve_job). Work that needs no approval is
  -- authorized by the worker after its independent review.
  if p_to = 'rejected' or (p_to = 'authorized' and (select requires_approval from public.jobs where id = p_job)) then raise exception 'only an agency approval can authorize or reject'; end if;
  return private.move_job(p_job, p_to, 'agent', p_actor, p_note, p_data);
end;
$$;

create or replace function public.record_review(p_job uuid, p_reviewer text, p_verdict text, p_rationale text default null, p_evidence jsonb default null)
returns public.reviews language plpgsql security definer set search_path = '' as $$
declare j public.jobs; r public.reviews;
begin
  select * into j from public.jobs where id = p_job;
  if j.id is null then raise exception 'job not found'; end if;
  if j.status <> 'awaiting_review' then raise exception 'job is not waiting for review'; end if;
  insert into public.reviews (job_id, org_id, reviewer, producer, verdict, rationale, evidence)
    values (j.id, j.org_id, p_reviewer, coalesce(j.agent, 'unknown'), p_verdict, p_rationale, p_evidence) returning * into r;
  return r;
end;
$$;

create or replace function public.claim_job(p_worker text, p_lease_seconds int default 600)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs;
begin
  select * into j from public.jobs q
   where q.status = 'queued' and (q.not_before is null or q.not_before <= now())
     and not exists (select 1 from public.jobs d where d.id = any (q.depends_on) and d.status <> 'completed')
   order by q.priority, q.created_at limit 1 for update skip locked;
  if j.id is null then return null; end if;
  update public.jobs set lease_owner = p_worker, lease_until = now() + make_interval(secs => least(greatest(p_lease_seconds, 30), 3600)) where id = j.id;
  return private.move_job(j.id, 'running', 'agent', p_worker, 'claimed');
end;
$$;

create or replace function public.fail_job(p_job uuid, p_actor text, p_error text)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs;
begin
  update public.jobs set error = left(p_error, 1000) where id = p_job;
  j := private.move_job(p_job, 'failed', 'agent', p_actor, left(p_error, 300));
  if j.attempts < j.max_attempts then
    update public.jobs set not_before = now() + make_interval(mins => 5 * j.attempts) where id = j.id;
    return private.move_job(j.id, 'queued', 'system', 'retry', 'retry ' || (j.attempts + 1) || ' of ' || j.max_attempts);
  end if;
  return private.move_job(j.id, 'escalated', 'system', 'retry', 'retry cap reached');
end;
$$;

-- Client submissions: untrusted advisory input. Never creates or changes a job by itself. --------------------------------
create table public.submissions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.orgs (id) on delete cascade,
  site_id uuid not null references public.sites (id) on delete cascade,
  submitted_by uuid not null references auth.users (id),
  submitted_by_client boolean not null,
  kind text not null check (kind in ('plan', 'document', 'keyword', 'file', 'suggestion', 'feedback')),
  title text not null check (length(title) between 1 and 200),
  body text check (body is null or length(body) <= 20000),
  file_path text check (file_path is null or file_path ~ '^submissions/[0-9a-f-]{36}/[A-Za-z0-9._-]{1,120}$'),
  status text not null default 'received' check (status in ('received', 'analyzing', 'awaiting_agency', 'accepted', 'rejected', 'needs_clarification')),
  analysis jsonb, -- SEO God's private analysis, never shown to the client
  agency_note text,
  decided_by uuid references auth.users (id), decided_at timestamptz,
  job_id uuid references public.jobs (id) on delete set null,
  created_at timestamptz not null default now()
);
create index submissions_site_idx on public.submissions (site_id, created_at desc);

create or replace function public.submit_to_agency(p_site uuid, p_kind text, p_title text, p_body text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare s public.submissions; v_client boolean := private.is_client_viewer(p_site);
begin
  if not v_client and not private.is_agency_for_site(p_site) then raise exception 'not allowed'; end if;
  if v_client and (select count(*) from public.submissions where submitted_by = (select auth.uid()) and created_at > now() - interval '1 day') >= 30 then
    raise exception 'at most 30 submissions a day'; end if;
  insert into public.submissions (org_id, site_id, submitted_by, submitted_by_client, kind, title, body)
    values (private.site_org(p_site), p_site, (select auth.uid()), v_client, p_kind, trim(p_title), nullif(trim(coalesce(p_body, '')), ''))
    returning * into s;
  insert into public.audit_log (org_id, site_id, actor, action, target) values (s.org_id, s.site_id, s.submitted_by, 'submission.create', s.id::text);
  return jsonb_build_object('id', s.id, 'status', s.status, 'created_at', s.created_at);
end;
$$;

-- Agency decides; accepting creates a proposed job that still needs agency approval before anything runs.
create or replace function public.review_submission(p_submission uuid, p_decision text, p_note text default null, p_job_kind text default 'client_request', p_risk text default 'medium')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare s public.submissions; j public.jobs;
begin
  select * into s from public.submissions where id = p_submission for update;
  if s.id is null or not private.is_member(s.org_id) then raise exception 'not allowed'; end if;
  if p_decision not in ('accepted', 'rejected', 'needs_clarification') then raise exception 'decision must be accepted, rejected or needs_clarification'; end if;
  if s.status in ('accepted', 'rejected') then raise exception 'submission already decided'; end if;
  if p_decision = 'accepted' then
    insert into public.jobs (org_id, site_id, kind, title, source, priority, risk, requires_approval, inputs, created_by)
      values (s.org_id, s.site_id, p_job_kind, s.title, 'client_submission', 1, p_risk, true, jsonb_build_object('submission', s.id, 'untrusted', true), (select auth.uid()))
      returning * into j;
    insert into public.job_events (job_id, org_id, actor_kind, actor, to_status, note) values (j.id, j.org_id, 'user', (select auth.uid())::text, 'proposed', 'from client submission');
  end if;
  update public.submissions set status = p_decision, agency_note = nullif(trim(coalesce(p_note, '')), ''), decided_by = (select auth.uid()), decided_at = now(), job_id = j.id
    where id = s.id returning * into s;
  insert into public.audit_log (org_id, site_id, actor, action, target, data) values (s.org_id, s.site_id, (select auth.uid()), 'submission.' || p_decision, s.id::text, jsonb_build_object('job', j.id));
  return jsonb_build_object('id', s.id, 'status', s.status, 'job', j.id);
end;
$$;

-- What a client sees of a submission: its own status and the agency's note; never the SEO God analysis.
create or replace function public.my_submissions(p_site uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'kind', s.kind, 'title', s.title, 'status', s.status, 'agency_note', s.agency_note, 'created_at', s.created_at) order by s.created_at desc), '[]'::jsonb)
  from public.submissions s
  where s.site_id = p_site and (private.is_agency_for_site(p_site) or (private.is_client_viewer(p_site) and s.submitted_by_client));
$$;

-- What a client sees of a site: results only. Agent runs, plans, issue links, drafts and integration internals are removed.
create or replace function public.client_sites()
returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('site', jsonb_build_object('id', s.id, 'name', s.name, 'url', s.url, 'status', s.status, 'last_snapshot_at', s.last_snapshot_at),
    'data', (select x.data - array['runs', 'plan', 'planAt', 'issues', 'drafts', 'proposals', 'candidates', 'integrations', 'source', 'digest'] from public.site_snapshots x where x.site_id = s.id order by x.taken_at desc limit 1),
    'brand', (select jsonb_build_object('name', coalesce(o.brand_name, o.name), 'color', o.brand_color) from public.orgs o where o.id = s.org_id)
  ) order by s.name), '[]'::jsonb)
  from public.sites s join public.client_members m on m.client_id = s.client_id and m.user_id = (select auth.uid());
$$;

-- Private site memory, integrations (no secrets) and the audit log. ------------------------------------------------------
create table public.site_memory (
  id bigserial primary key,
  org_id uuid not null, site_id uuid not null references public.sites (id) on delete cascade,
  kind text not null check (kind in ('identity', 'brand', 'strategy', 'objective', 'decision', 'experiment', 'lesson', 'failure', 'question', 'answer')),
  key text not null check (length(key) between 1 and 120),
  value jsonb not null,
  basis text not null check (basis in ('stated', 'inferred', 'verified', 'answered')),
  confidence numeric(3, 2) check (confidence is null or confidence between 0 and 1),
  source text,
  created_by text not null,
  created_at timestamptz not null default now(),
  superseded_at timestamptz
);
create index site_memory_site_idx on public.site_memory (site_id, kind, key) where superseded_at is null;

create table public.integrations (
  id bigserial primary key,
  org_id uuid not null, site_id uuid not null references public.sites (id) on delete cascade,
  provider text not null check (provider in ('search_console', 'ga4', 'github', 'crawler', 'bing_webmaster', 'google_sheets', 'other')),
  scope text not null check (scope in ('read', 'write')),
  status text not null default 'unconnected' check (status in ('unconnected', 'connected', 'error', 'revoked')),
  detail jsonb, -- property id, repository name; never a secret
  last_ok_at timestamptz, last_error text,
  created_at timestamptz not null default now(),
  unique (site_id, provider, scope)
);

create table public.audit_log (
  id bigserial primary key,
  org_id uuid not null, site_id uuid,
  actor uuid, action text not null, target text, data jsonb,
  at timestamptz not null default now()
);
create index audit_log_org_idx on public.audit_log (org_id, at desc);

create trigger jobs_same_org before insert or update of site_id, org_id on public.jobs for each row execute function private.row_same_org();
create trigger submissions_same_org before insert or update of site_id, org_id on public.submissions for each row execute function private.row_same_org();
create trigger site_memory_same_org before insert or update of site_id, org_id on public.site_memory for each row execute function private.row_same_org();
create trigger integrations_same_org before insert or update of site_id, org_id on public.integrations for each row execute function private.row_same_org();

-- Row level security: agency members read their org's rows; client viewers read nothing here directly (they use
-- client_sites and my_submissions). Writes only through the functions above. ------------------------------------------
alter table public.clients enable row level security;
alter table public.client_members enable row level security;
alter table public.client_invites enable row level security;
alter table public.jobs enable row level security;
alter table public.job_events enable row level security;
alter table public.reviews enable row level security;
alter table public.approvals enable row level security;
alter table public.submissions enable row level security;
alter table public.site_memory enable row level security;
alter table public.integrations enable row level security;
alter table public.audit_log enable row level security;
create policy clients_select on public.clients for select to authenticated using ((select private.is_member(org_id)));
create policy client_members_select on public.client_members for select to authenticated using ((select private.is_member(private.client_org(client_id))));
create policy client_invites_select on public.client_invites for select to authenticated using ((select private.is_member(private.client_org(client_id))));
create policy jobs_select on public.jobs for select to authenticated using ((select private.is_member(org_id)));
create policy job_events_select on public.job_events for select to authenticated using ((select private.is_member(org_id)));
create policy reviews_select on public.reviews for select to authenticated using ((select private.is_member(org_id)));
create policy approvals_select on public.approvals for select to authenticated using ((select private.is_member(org_id)));
create policy submissions_select on public.submissions for select to authenticated using ((select private.is_member(org_id)));
create policy site_memory_select on public.site_memory for select to authenticated using ((select private.is_member(org_id)));
create policy integrations_select on public.integrations for select to authenticated using ((select private.is_member(org_id)));
create policy audit_log_select on public.audit_log for select to authenticated using ((select private.is_owner(org_id)));
revoke all on public.clients, public.client_members, public.client_invites, public.jobs, public.job_events, public.reviews, public.approvals,
  public.submissions, public.site_memory, public.integrations, public.audit_log from anon, authenticated;
grant select on public.clients, public.client_members, public.client_invites, public.jobs, public.job_events, public.reviews, public.approvals,
  public.submissions, public.site_memory, public.integrations, public.audit_log to authenticated;
grant all on public.clients, public.client_members, public.client_invites, public.jobs, public.job_events, public.reviews, public.approvals,
  public.submissions, public.site_memory, public.integrations, public.audit_log to service_role;
grant usage on all sequences in schema public to service_role;

-- Agency management of clients (owners and members).
create or replace function public.create_client(p_name text, p_org uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; c public.clients;
begin
  v_org := coalesce(p_org, (select m.org_id from public.org_members m where m.user_id = (select auth.uid()) order by m.created_at limit 1));
  if v_org is null or not private.is_member(v_org) then raise exception 'not allowed'; end if;
  insert into public.clients (org_id, name) values (v_org, trim(p_name)) returning * into c;
  insert into public.audit_log (org_id, actor, action, target) values (v_org, (select auth.uid()), 'client.create', c.id::text);
  return to_jsonb(c);
end;
$$;
create or replace function public.assign_site_client(p_site uuid, p_client uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not private.is_agency_for_site(p_site) or private.client_org(p_client) is distinct from private.site_org(p_site) then raise exception 'not allowed'; end if;
  update public.sites set client_id = p_client where id = p_site;
  insert into public.audit_log (org_id, site_id, actor, action, target) values (private.site_org(p_site), p_site, (select auth.uid()), 'site.assign_client', p_client::text);
end;
$$;
create or replace function public.invite_client_user(p_client uuid, p_email text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.client_org(p_client); v_email text := lower(trim(p_email)); v_user uuid;
begin
  if v_org is null or not private.is_member(v_org) then raise exception 'not allowed'; end if;
  if exists (select 1 from public.org_members m join auth.users u on u.id = m.user_id where lower(u.email) = v_email) then raise exception 'that person is agency staff'; end if;
  insert into public.client_invites (client_id, email, invited_by) values (p_client, v_email, (select auth.uid())) on conflict (client_id, email) do nothing;
  select id into v_user from auth.users where lower(email) = v_email;
  if v_user is not null then
    insert into public.client_members (client_id, user_id) values (p_client, v_user) on conflict do nothing;
    update public.client_invites set accepted_at = now() where client_id = p_client and email = v_email;
  end if;
  insert into public.audit_log (org_id, actor, action, target) values (v_org, (select auth.uid()), 'client.invite', v_email);
  return jsonb_build_object('client', p_client, 'email', v_email, 'joined', v_user is not null);
end;
$$;

revoke all on function private.move_job(uuid, text, text, text, text, jsonb), public.create_job(uuid, text, text, text, text, boolean, int, jsonb, text, text, uuid[], numeric),
  public.approve_job(uuid, text, text), public.transition_job(uuid, text, text, text, jsonb), public.record_review(uuid, text, text, text, jsonb),
  public.claim_job(text, int), public.fail_job(uuid, text, text), public.submit_to_agency(uuid, text, text, text),
  public.review_submission(uuid, text, text, text, text), public.my_submissions(uuid), public.client_sites(),
  public.create_client(text, uuid), public.assign_site_client(uuid, uuid), public.invite_client_user(uuid, text) from public, anon, authenticated;
grant execute on function public.create_job(uuid, text, text, text, text, boolean, int, jsonb, text, text, uuid[], numeric), public.approve_job(uuid, text, text),
  public.submit_to_agency(uuid, text, text, text), public.review_submission(uuid, text, text, text, text), public.my_submissions(uuid), public.client_sites(),
  public.create_client(text, uuid), public.assign_site_client(uuid, uuid), public.invite_client_user(uuid, text) to authenticated;
grant execute on function public.create_job(uuid, text, text, text, text, boolean, int, jsonb, text, text, uuid[], numeric), public.transition_job(uuid, text, text, text, jsonb),
  public.record_review(uuid, text, text, text, jsonb), public.claim_job(text, int), public.fail_job(uuid, text, text) to service_role;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108000000', 'r1_contracts');

-- ===== 20261108010000_r1_memory.sql =====
-- Site memory writes for workers (service role): a new value for the same (site, kind, key) supersedes the old one, so
-- history is kept and the current view is "superseded_at is null". Reads by kind for the worker. Not applied anywhere.
create or replace function public.remember(p_site uuid, p_items jsonb, p_actor text default 'seo-god')
returns int language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.site_org(p_site); it jsonb; n int := 0;
begin
  if v_org is null then raise exception 'site not found'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 500 then raise exception 'items must be an array of at most 500'; end if;
  for it in select * from jsonb_array_elements(p_items) loop
    update public.site_memory set superseded_at = now()
      where site_id = p_site and kind = it->>'kind' and key = it->>'key' and superseded_at is null and value is distinct from it->'value';
    if not exists (select 1 from public.site_memory where site_id = p_site and kind = it->>'kind' and key = it->>'key' and superseded_at is null) then
      insert into public.site_memory (org_id, site_id, kind, key, value, basis, confidence, source, created_by)
        values (v_org, p_site, it->>'kind', it->>'key', coalesce(it->'value', 'null'::jsonb), it->>'basis', nullif(it->>'confidence', '')::numeric, it->>'source', p_actor);
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$$;

create or replace function public.recall(p_site uuid, p_kind text default null)
returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('kind', m.kind, 'key', m.key, 'value', m.value, 'basis', m.basis, 'confidence', m.confidence, 'source', m.source, 'at', m.created_at) order by m.kind, m.key), '[]'::jsonb)
  from public.site_memory m where m.site_id = p_site and m.superseded_at is null and (p_kind is null or m.kind = p_kind);
$$;

revoke all on function public.remember(uuid, jsonb, text), public.recall(uuid, text) from public, anon, authenticated;
grant execute on function public.remember(uuid, jsonb, text), public.recall(uuid, text) to service_role;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108010000', 'r1_memory');

-- ===== 20261108020000_r1_scheduler.sql =====
-- SEO God scheduler support (R1-A2, D28): what the scheduler needs from the database to run every site on its own,
-- within a daily budget, with every cent recorded. Service role only (the worker); agency members can read their own
-- costs. Not applied anywhere.

-- Compact reports (the last audit summary) and agency settings live in site memory too.
alter table public.site_memory drop constraint if exists site_memory_kind_check;
alter table public.site_memory add constraint site_memory_kind_check
  check (kind in ('identity', 'brand', 'strategy', 'objective', 'decision', 'experiment', 'lesson', 'failure', 'question', 'answer', 'report', 'setting'));

-- One row per charge, so a day's spend is exact even when a job runs across midnight or is retried.
create table public.job_costs (
  id bigserial primary key,
  org_id uuid not null, site_id uuid not null references public.sites (id) on delete cascade,
  job_id uuid not null references public.jobs (id) on delete cascade,
  usd numeric(10, 4) not null check (usd >= 0),
  note text,
  at timestamptz not null default now()
);
create index job_costs_site_at_idx on public.job_costs (site_id, at);
create trigger job_costs_same_org before insert or update of site_id, org_id on public.job_costs for each row execute function private.row_same_org();
alter table public.job_costs enable row level security;
create policy job_costs_select on public.job_costs for select to authenticated using ((select private.is_member(org_id)));

-- Sites the scheduler plans for: every site that is not paused by its agency.
create or replace function public.god_sites()
returns table (id uuid, org_id uuid, name text, url text, status text) language sql stable security definer set search_path = '' as $$
  select s.id, s.org_id, s.name, s.url, s.status from public.sites s where s.status <> 'paused' order by s.created_at;
$$;

-- A site's jobs that still matter to planning (open ones, plus the last 30 days of finished ones).
create or replace function public.site_jobs(p_site uuid)
returns setof public.jobs language sql stable security definer set search_path = '' as $$
  select * from public.jobs j where j.site_id = p_site
     and (j.status not in ('completed', 'cancelled', 'rejected') or j.updated_at > now() - interval '30 days')
   order by j.created_at;
$$;

-- What the handler produced (shown to the agency when it approves) and what it cost.
create or replace function public.record_job_output(p_job uuid, p_outputs jsonb, p_cost numeric default 0, p_note text default null)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs;
begin
  if coalesce(p_cost, 0) < 0 then raise exception 'cost cannot be negative'; end if;
  update public.jobs set outputs = coalesce(p_outputs, outputs), cost_usd = cost_usd + coalesce(p_cost, 0), updated_at = now()
   where id = p_job returning * into j;
  if j.id is null then raise exception 'job not found'; end if;
  if coalesce(p_cost, 0) > 0 then insert into public.job_costs (org_id, site_id, job_id, usd, note) values (j.org_id, j.site_id, j.id, p_cost, p_note); end if;
  return j;
end;
$$;

create or replace function public.site_spend(p_site uuid, p_since timestamptz)
returns numeric language sql stable security definer set search_path = '' as $$
  select coalesce(sum(c.usd), 0) from public.job_costs c where c.site_id = p_site and c.at >= p_since;
$$;

revoke all on function public.god_sites(), public.site_jobs(uuid), public.record_job_output(uuid, jsonb, numeric, text), public.site_spend(uuid, timestamptz) from public, anon, authenticated;
grant execute on function public.god_sites(), public.site_jobs(uuid), public.record_job_output(uuid, jsonb, numeric, text), public.site_spend(uuid, timestamptz) to service_role;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108020000', 'r1_scheduler');

-- ===== 20261108030000_cloudflare_execution.sql =====
-- Cloudflare execution support (D30). The Cloudflare Worker is a stateless scheduler and dispatcher; everything durable
-- stays here: which sites are due, a pause switch that works without a redeploy, recovery of jobs whose Worker died,
-- and one row per scheduler run for monitoring and free-tier usage. Service role only. Not applied anywhere.

-- Pause switch, read by every scheduler run: pausing needs no deploy and no access to Cloudflare.
create table public.god_control (
  id int primary key default 1 check (id = 1),
  paused boolean not null default false,
  reason text,
  updated_at timestamptz not null default now()
);
insert into public.god_control (id) values (1);

-- When the scheduler last planned each site, so planning rotates through all sites within the request limits.
create table public.god_site_ticks (
  site_id uuid primary key references public.sites (id) on delete cascade,
  org_id uuid not null,
  ticked_at timestamptz not null default now(),
  outcome jsonb
);
create trigger god_site_ticks_same_org before insert or update of site_id, org_id on public.god_site_ticks for each row execute function private.row_same_org();

-- One row per scheduler run: what it did and what it used, for monitoring and the free-tier dashboard.
create table public.god_runs (
  id bigserial primary key,
  runner text not null check (length(runner) between 1 and 80),
  started_at timestamptz not null,
  finished_at timestamptz not null default now(),
  sites_planned int not null default 0,
  jobs_run int not null default 0,
  jobs_recovered int not null default 0,
  invocations int not null default 0,     -- Worker invocations this run caused (itself and its fan-out)
  subrequests int not null default 0,     -- outbound requests the run made (Supabase, providers)
  errors jsonb not null default '[]',
  paused boolean not null default false
);
create index god_runs_started_idx on public.god_runs (started_at desc);

alter table public.god_control enable row level security;
alter table public.god_site_ticks enable row level security;
alter table public.god_runs enable row level security;
-- Agency members may see when their own sites were last planned; nothing else here is readable outside the service role.
create policy god_site_ticks_select on public.god_site_ticks for select to authenticated using ((select private.is_member(org_id)));

create or replace function public.god_paused()
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select paused from public.god_control where id = 1), true); -- missing row: stay paused
$$;

create or replace function public.set_god_paused(p_paused boolean, p_reason text default null)
returns boolean language sql security definer set search_path = '' as $$
  update public.god_control set paused = p_paused, reason = p_reason, updated_at = now() where id = 1 returning paused;
$$;

-- Sites to plan in this run: any site with an agency decision to carry out first, then the least recently planned,
-- skipping sites planned within p_min_age. Paused sites are never returned.
create or replace function public.god_due_sites(p_limit int default 5, p_min_age interval default interval '6 hours')
returns table (id uuid, org_id uuid, name text, url text) language sql stable security definer set search_path = '' as $$
  select s.id, s.org_id, s.name, s.url from public.sites s
    left join public.god_site_ticks t on t.site_id = s.id
   where s.status <> 'paused'
     and (t.ticked_at is null or t.ticked_at < now() - p_min_age
          or exists (select 1 from public.jobs j where j.site_id = s.id and j.status = 'authorized'))
   order by exists (select 1 from public.jobs j where j.site_id = s.id and j.status = 'authorized') desc, t.ticked_at nulls first, s.created_at
   limit least(greatest(p_limit, 1), 50);
$$;

create or replace function public.record_site_tick(p_site uuid, p_outcome jsonb default null)
returns void language sql security definer set search_path = '' as $$
  insert into public.god_site_ticks (site_id, org_id, ticked_at, outcome) values (p_site, private.site_org(p_site), now(), p_outcome)
  on conflict (site_id) do update set ticked_at = now(), outcome = excluded.outcome;
$$;

-- A Worker can be killed mid-job (CPU limit, deploy, crash). Jobs still "running" after their lease are failed through
-- the normal path, so they retry within the cap or escalate; nothing stays stuck and nothing runs twice at once.
create or replace function public.reap_expired_leases(p_limit int default 20)
returns int language plpgsql security definer set search_path = '' as $$
declare r record; n int := 0;
begin
  for r in select id from public.jobs where status = 'running' and lease_until < now() order by lease_until limit least(greatest(p_limit, 1), 100) for update skip locked loop
    perform public.fail_job(r.id, 'reaper', 'lease expired: the worker stopped before finishing');
    n := n + 1;
  end loop;
  return n;
end;
$$;

create or replace function public.record_god_run(p_run jsonb)
returns bigint language sql security definer set search_path = '' as $$
  insert into public.god_runs (runner, started_at, sites_planned, jobs_run, jobs_recovered, invocations, subrequests, errors, paused)
  values (left(coalesce(p_run->>'runner', 'unknown'), 80), coalesce((p_run->>'startedAt')::timestamptz, now()), coalesce((p_run->>'sitesPlanned')::int, 0),
          coalesce((p_run->>'jobsRun')::int, 0), coalesce((p_run->>'jobsRecovered')::int, 0), coalesce((p_run->>'invocations')::int, 0),
          coalesce((p_run->>'subrequests')::int, 0), coalesce(p_run->'errors', '[]'::jsonb), coalesce((p_run->>'paused')::boolean, false))
  returning id;
$$;

-- Free-tier usage for the last p_days, from the runs themselves (the Cloudflare dashboard remains the authority).
create or replace function public.god_usage(p_days int default 1)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('runs', count(*), 'invocations', coalesce(sum(invocations), 0), 'subrequests', coalesce(sum(subrequests), 0),
    'jobsRun', coalesce(sum(jobs_run), 0), 'sitesPlanned', coalesce(sum(sites_planned), 0), 'jobsRecovered', coalesce(sum(jobs_recovered), 0),
    'runsWithErrors', count(*) filter (where jsonb_array_length(errors) > 0), 'since', now() - make_interval(days => p_days))
  from public.god_runs where started_at > now() - make_interval(days => least(greatest(p_days, 1), 90));
$$;

grant select, insert, update, delete on public.god_control, public.god_site_ticks, public.god_runs to service_role;
grant usage on all sequences in schema public to service_role;
revoke all on function public.god_paused(), public.set_god_paused(boolean, text), public.god_due_sites(int, interval), public.record_site_tick(uuid, jsonb),
  public.reap_expired_leases(int), public.record_god_run(jsonb), public.god_usage(int) from public, anon, authenticated;
grant execute on function public.god_paused(), public.set_god_paused(boolean, text), public.god_due_sites(int, interval), public.record_site_tick(uuid, jsonb),
  public.reap_expired_leases(int), public.record_god_run(jsonb), public.god_usage(int) to service_role;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108030000', 'cloudflare_execution');

-- ===== 20261108040000_agency_console.sql =====
-- Agency console for the SEO God (R1-P2, agency side): what an agency member needs to run a site's SEO God from the
-- portal. Approvals themselves already exist (public.approve_job, agency only). This adds:
--   god_console(site)       one read with the strategy, open questions, work waiting for the agency, escalations,
--                           recent results and costs; agency members of the site's org only.
--   answer_question(...)    an agency member answers an onboarding question; it becomes site memory (basis
--                           "answered") and closes the question.
--   retry_job(job, note)    an agency member sends escalated work back to the queue. The lifecycle still applies:
--                           gated work needs a standing approval before it can be queued.
-- Clients get none of this: they are not members of the agency org (D27), and these functions check membership.
-- Not applied anywhere.

create or replace function public.god_console(p_site uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_org uuid := private.site_org(p_site);
begin
  if v_org is null or not private.is_member(v_org) then raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'strategy', (select m.value from public.site_memory m where m.site_id = p_site and m.kind = 'strategy' and m.key = 'initial' and m.superseded_at is null limit 1),
    'questions', coalesce((select jsonb_agg(jsonb_build_object('key', m.key, 'question', m.value->>'question', 'why', m.value->>'why') order by m.key)
                  from public.site_memory m where m.site_id = p_site and m.kind = 'question' and m.superseded_at is null
                   and not exists (select 1 from public.site_memory a where a.site_id = p_site and a.kind = 'answer' and a.key = m.key and a.superseded_at is null)), '[]'::jsonb),
    'answers', coalesce((select jsonb_agg(jsonb_build_object('key', m.key, 'value', m.value->>'value', 'at', m.created_at) order by m.key)
                  from public.site_memory m where m.site_id = p_site and m.kind = 'answer' and m.superseded_at is null), '[]'::jsonb),
    'facts', (select count(*) from public.site_memory m where m.site_id = p_site and m.kind in ('identity', 'brand') and m.superseded_at is null),
    'waiting', coalesce((select jsonb_agg(jsonb_build_object('id', j.id, 'kind', j.kind, 'title', j.title, 'risk', j.risk, 'priority', j.priority, 'source', j.source,
                    'why', j.objective, 'stage', case when j.attempts > 0 then 'result' else 'start' end, 'outputs', j.outputs, 'costUsd', j.cost_usd, 'budgetUsd', j.budget_usd,
                    'review', (select jsonb_build_object('verdict', r.verdict, 'reviewer', r.reviewer, 'rationale', r.rationale) from public.reviews r where r.job_id = j.id order by r.id desc limit 1),
                    'createdAt', j.created_at) order by j.priority, j.created_at)
                  from public.jobs j where j.site_id = p_site and j.status = 'awaiting_approval'), '[]'::jsonb),
    'escalated', coalesce((select jsonb_agg(jsonb_build_object('id', j.id, 'kind', j.kind, 'title', j.title, 'error', j.error, 'attempts', j.attempts, 'updatedAt', j.updated_at) order by j.updated_at desc)
                  from public.jobs j where j.site_id = p_site and j.status = 'escalated'), '[]'::jsonb),
    'active', coalesce((select jsonb_agg(jsonb_build_object('id', j.id, 'kind', j.kind, 'title', j.title, 'status', j.status) order by j.priority, j.created_at)
                  from public.jobs j where j.site_id = p_site and j.status in ('scoped', 'queued', 'running', 'awaiting_review', 'authorized', 'deploying', 'verifying')), '[]'::jsonb),
    'recent', coalesce((select jsonb_agg(x order by x->>'updatedAt' desc) from (
                  select jsonb_build_object('id', j.id, 'kind', j.kind, 'title', j.title, 'status', j.status, 'outputs', j.outputs, 'costUsd', j.cost_usd, 'updatedAt', j.updated_at) x
                    from public.jobs j where j.site_id = p_site and j.status in ('completed', 'rejected', 'failed', 'cancelled') order by j.updated_at desc limit 20) t), '[]'::jsonb),
    'costs', jsonb_build_object(
      'today', coalesce((select sum(c.usd) from public.job_costs c where c.site_id = p_site and c.at >= date_trunc('day', now())), 0),
      'month', coalesce((select sum(c.usd) from public.job_costs c where c.site_id = p_site and c.at >= date_trunc('month', now())), 0)),
    'lastPlanned', (select jsonb_build_object('at', t.ticked_at, 'outcome', t.outcome) from public.god_site_ticks t where t.site_id = p_site));
end;
$$;

create or replace function public.answer_question(p_site uuid, p_key text, p_value text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.site_org(p_site); v text := trim(coalesce(p_value, ''));
begin
  if v_org is null or not private.is_member(v_org) then raise exception 'not allowed'; end if;
  if v = '' or length(v) > 2000 then raise exception 'answer must be 1 to 2000 characters'; end if;
  if not exists (select 1 from public.site_memory m where m.site_id = p_site and m.kind = 'question' and m.key = p_key and m.superseded_at is null) then raise exception 'no such question for this site'; end if;
  update public.site_memory set superseded_at = now() where site_id = p_site and kind = 'answer' and key = p_key and superseded_at is null;
  insert into public.site_memory (org_id, site_id, kind, key, value, basis, confidence, source, created_by)
    values (v_org, p_site, 'answer', p_key, jsonb_build_object('value', v), 'answered', 1, 'agency answer', (select auth.uid())::text);
  insert into public.audit_log (org_id, site_id, actor, action, target, data) values (v_org, p_site, (select auth.uid()), 'memory.answer', p_key, null);
  return jsonb_build_object('key', p_key, 'value', v);
end;
$$;

create or replace function public.retry_job(p_job uuid, p_note text default null)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs;
begin
  select * into j from public.jobs where id = p_job;
  if j.id is null or not private.is_member(j.org_id) then raise exception 'not allowed'; end if;
  if j.status <> 'escalated' then raise exception 'only escalated work can be retried'; end if;
  insert into public.audit_log (org_id, site_id, actor, action, target, data) values (j.org_id, j.site_id, (select auth.uid()), 'job.retry', j.id::text, jsonb_build_object('note', p_note));
  update public.jobs set attempts = 0, error = null, not_before = null where id = j.id; -- a person decided to try again: a fresh set of attempts
  return private.move_job(j.id, 'queued', 'user', (select auth.uid())::text, coalesce(nullif(trim(coalesce(p_note, '')), ''), 'retried by the agency'));
end;
$$;

revoke all on function public.god_console(uuid), public.answer_question(uuid, text, text), public.retry_job(uuid, text) from public, anon;
grant execute on function public.god_console(uuid), public.answer_question(uuid, text, text), public.retry_job(uuid, text) to authenticated;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108040000', 'agency_console');

-- ===== 20261108050000_client_portal.sql =====
-- Client portal, both sides (R1-P2). Owner decisions: clients get reporting plus advisory submissions only; a
-- submission never starts work by itself; only the agency approves. Built on D27's submissions and client accounts.
--   agency_inbox(site)           agency members: the site's client (members, pending invites), the org's clients, and
--                                every submission with its full text and who sent it.
--   review_submission(...)       replaced: an accepted request becomes a job with a budget (it was 0, so it could never
--                                run) and still requires the agency's approval before anything runs.
--   submission_for_job(job)      the worker (service role only) reads the request text of the job it runs; the text is
--                                untrusted and is handled as data.
-- Not applied anywhere.

create or replace function public.agency_inbox(p_site uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_org uuid := private.site_org(p_site); v_client uuid;
begin
  if v_org is null or not private.is_member(v_org) then raise exception 'not allowed'; end if;
  select client_id into v_client from public.sites where id = p_site;
  return jsonb_build_object(
    'client', (select jsonb_build_object('id', c.id, 'name', c.name,
        'members', coalesce((select jsonb_agg(u.email order by u.email) from public.client_members m join auth.users u on u.id = m.user_id where m.client_id = c.id), '[]'::jsonb),
        'invites', coalesce((select jsonb_agg(jsonb_build_object('email', i.email, 'accepted', i.accepted_at is not null) order by i.email) from public.client_invites i where i.client_id = c.id), '[]'::jsonb))
      from public.clients c where c.id = v_client),
    'clients', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name) order by c.name) from public.clients c where c.org_id = v_org), '[]'::jsonb),
    'submissions', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'kind', s.kind, 'title', s.title, 'body', s.body, 'status', s.status, 'agencyNote', s.agency_note,
        'byClient', s.submitted_by_client, 'by', (select u.email from auth.users u where u.id = s.submitted_by), 'createdAt', s.created_at, 'decidedAt', s.decided_at,
        'job', (select jsonb_build_object('id', j.id, 'status', j.status) from public.jobs j where j.id = s.job_id)) order by s.created_at desc)
      from public.submissions s where s.site_id = p_site), '[]'::jsonb));
end;
$$;

drop function if exists public.review_submission(uuid, text, text, text, text);
create or replace function public.review_submission(p_submission uuid, p_decision text, p_note text default null, p_job_kind text default 'client_request', p_risk text default 'medium', p_budget_usd numeric default 0.5)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare s public.submissions; j public.jobs;
begin
  select * into s from public.submissions where id = p_submission for update;
  if s.id is null or not private.is_member(s.org_id) then raise exception 'not allowed'; end if;
  if p_decision not in ('accepted', 'rejected', 'needs_clarification') then raise exception 'decision must be accepted, rejected or needs_clarification'; end if;
  if s.status in ('accepted', 'rejected') then raise exception 'submission already decided'; end if;
  if p_risk not in ('low', 'medium', 'high') then raise exception 'risk must be low, medium or high'; end if;
  if coalesce(p_budget_usd, 0) < 0 or p_budget_usd > 50 then raise exception 'budget must be between 0 and 50'; end if;
  if p_decision = 'accepted' then
    -- Always gated: accepting a request lets the SEO God work on it; nothing runs until the agency approves the job.
    insert into public.jobs (org_id, site_id, kind, title, source, priority, risk, requires_approval, inputs, budget_usd, created_by)
      values (s.org_id, s.site_id, p_job_kind, s.title, 'client_submission', 1, p_risk, true, jsonb_build_object('submission', s.id, 'untrusted', true), coalesce(p_budget_usd, 0), (select auth.uid()))
      returning * into j;
    insert into public.job_events (job_id, org_id, actor_kind, actor, to_status, note) values (j.id, j.org_id, 'user', (select auth.uid())::text, 'proposed', 'from client submission');
  end if;
  update public.submissions set status = p_decision, agency_note = nullif(trim(coalesce(p_note, '')), ''), decided_by = (select auth.uid()), decided_at = now(), job_id = j.id
    where id = s.id returning * into s;
  insert into public.audit_log (org_id, site_id, actor, action, target, data) values (s.org_id, s.site_id, (select auth.uid()), 'submission.' || p_decision, s.id::text, jsonb_build_object('job', j.id));
  return jsonb_build_object('id', s.id, 'status', s.status, 'job', j.id);
end;
$$;

create or replace function public.submission_for_job(p_job uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('kind', s.kind, 'title', s.title, 'body', s.body, 'byClient', s.submitted_by_client)
    from public.jobs j join public.submissions s on s.id = (j.inputs->>'submission')::uuid and s.site_id = j.site_id
   where j.id = p_job;
$$;

revoke all on function public.agency_inbox(uuid), public.review_submission(uuid, text, text, text, text, numeric), public.submission_for_job(uuid) from public, anon, authenticated;
grant execute on function public.agency_inbox(uuid), public.review_submission(uuid, text, text, text, text, numeric) to authenticated;
grant execute on function public.submission_for_job(uuid) to service_role;

-- An accepted client request (status "proposed") makes its site due at once, like an agency approval does, so the
-- scheduler sends it to the agency for approval within one run instead of waiting for the site's planning slot.
create or replace function public.god_due_sites(p_limit int default 5, p_min_age interval default interval '6 hours')
returns table (id uuid, org_id uuid, name text, url text) language sql stable security definer set search_path = '' as $$
  select s.id, s.org_id, s.name, s.url from public.sites s
    left join public.god_site_ticks t on t.site_id = s.id
   where s.status <> 'paused'
     and (t.ticked_at is null or t.ticked_at < now() - p_min_age
          or exists (select 1 from public.jobs j where j.site_id = s.id and j.status in ('authorized', 'proposed')))
   order by exists (select 1 from public.jobs j where j.site_id = s.id and j.status in ('authorized', 'proposed')) desc, t.ticked_at nulls first, s.created_at
   limit least(greatest(p_limit, 1), 50);
$$;

