end;
$$;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108060000', 'learning');

-- ===== 20261108070000_operations.sql =====
-- Operations (D32): an overview for each agency of its own sites, and platform health for platform admins only.
-- Scheduler runs and the pause switch cover every agency, so they are never shown to an agency: an agency member
-- would otherwise see other tenants' activity and could pause everyone. Platform admins are an explicit list kept by
-- the service role (no self sign-up). Not applied anywhere.

create table public.platform_admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  added_at timestamptz not null default now(),
  note text
);
alter table public.platform_admins enable row level security; -- no policies: only the service role and the functions below read it
grant select, insert, delete on public.platform_admins to service_role;

alter table public.god_control add column if not exists updated_by uuid references auth.users (id) on delete set null;

create or replace function private.is_platform_admin()
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.platform_admins where user_id = (select auth.uid()));
$$;

-- Every site of the caller's agencies: what needs a person, what it costs, when it was last planned.
create or replace function public.agency_overview()
returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', s.id, 'name', s.name, 'url', s.url, 'status', s.status,
      'strategy', (select m.value->>'status' from public.site_memory m where m.site_id = s.id and m.kind = 'strategy' and m.key = 'initial' and m.superseded_at is null limit 1),
      'waiting', (select count(*) from public.jobs j where j.site_id = s.id and j.status = 'awaiting_approval'),
      'escalated', (select count(*) from public.jobs j where j.site_id = s.id and j.status = 'escalated'),
      'active', (select count(*) from public.jobs j where j.site_id = s.id and j.status in ('queued', 'running', 'awaiting_review', 'authorized')),
      'requests', (select count(*) from public.submissions x where x.site_id = s.id and x.status in ('received', 'needs_clarification')),
      'spendToday', coalesce((select sum(c.usd) from public.job_costs c where c.site_id = s.id and c.at >= date_trunc('day', now())), 0),
      'spendMonth', coalesce((select sum(c.usd) from public.job_costs c where c.site_id = s.id and c.at >= date_trunc('month', now())), 0),
      'lastPlanned', (select t.ticked_at from public.god_site_ticks t where t.site_id = s.id),
      'lastError', (select t.outcome->>'error' from public.god_site_ticks t where t.site_id = s.id)
    ) order by s.name), '[]'::jsonb)
  from public.sites s where private.is_member(s.org_id);
$$;

-- Platform admins only: scheduler state, recent runs and usage.
create or replace function public.platform_health(p_days int default 1)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_platform_admin() then raise exception 'not allowed'; end if;
  return jsonb_build_object(
    'control', (select jsonb_build_object('paused', c.paused, 'reason', c.reason, 'updatedAt', c.updated_at, 'by', (select u.email from auth.users u where u.id = c.updated_by)) from public.god_control c where c.id = 1),
    'usage', public.god_usage(p_days),
    'runs', coalesce((select jsonb_agg(to_jsonb(r) order by r.started_at desc) from (select id, runner, started_at, finished_at, sites_planned, jobs_run, jobs_recovered, invocations, subrequests, errors, paused from public.god_runs order by started_at desc limit 20) r), '[]'::jsonb),
    'lastRunAt', (select max(started_at) from public.god_runs),
    'sites', (select count(*) from public.sites), 'pausedSites', (select count(*) from public.sites where status = 'paused'));
end;
$$;

create or replace function public.set_platform_paused(p_paused boolean, p_reason text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
begin
  if not private.is_platform_admin() then raise exception 'not allowed'; end if;
  update public.god_control set paused = p_paused, reason = nullif(trim(coalesce(p_reason, '')), ''), updated_at = now(), updated_by = (select auth.uid()) where id = 1;
  return (select jsonb_build_object('paused', paused, 'reason', reason, 'updatedAt', updated_at) from public.god_control where id = 1);
end;
$$;

revoke all on function private.is_platform_admin(), public.agency_overview(), public.platform_health(int), public.set_platform_paused(boolean, text) from public, anon;
grant execute on function private.is_platform_admin() to authenticated;
grant execute on function public.agency_overview(), public.platform_health(int), public.set_platform_paused(boolean, text) to authenticated;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108070000', 'operations');

-- ===== 20261108080000_security_fixes.sql =====
-- Fixes from the independent security review of 2026-11-08 (D34). Not applied anywhere.
--
-- 1. Search Console with the platform's shared Google account could read any domain an agency added, including one it
--    does not own (another agency's client who had added the account would have their data shown to the attacker).
--    Now a site may use the shared account only when a platform admin has confirmed it (gsc_allowed), the confirmation
--    is cleared whenever the site's address changes, and never while the same domain is registered in another agency.
-- 2. Agency members could create jobs with any budget through create_job and bypass the per-site daily budget, spending
--    the platform's AI key. Member-created jobs now get at most $5 each, need the agency's approval when they carry a
--    budget, and at most 100 a day per agency. (The per-site daily cap is also enforced at run time by the engine.)

alter table public.sites add column if not exists gsc_allowed boolean not null default false,
  add column if not exists gsc_allowed_by uuid references auth.users (id) on delete set null,
  add column if not exists gsc_allowed_at timestamptz;
-- Members may not change it: their update grant lists only name, url, repo and status (20261030000000_portal.sql).

create or replace function private.site_host(p_url text)
returns text language sql immutable set search_path = '' as $$
  select regexp_replace(lower(split_part(split_part(regexp_replace(coalesce(p_url, ''), '^[a-z]+://', '', 'i'), '/', 1), ':', 1)), '^www\.', '');
$$;

create or replace function private.sites_gsc_reset()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.url is distinct from old.url then new.gsc_allowed := false; new.gsc_allowed_by := null; new.gsc_allowed_at := null; end if;
  return new;
end;
$$;
drop trigger if exists sites_gsc_reset on public.sites;
create trigger sites_gsc_reset before update of url on public.sites for each row execute function private.sites_gsc_reset();

-- Service role (the scan function, the Worker): may this site use the shared Google account right now?
create or replace function public.gsc_allowed(p_site uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select s.gsc_allowed and not exists (
      select 1 from public.sites o where o.org_id <> s.org_id and private.site_host(o.url) = private.site_host(s.url))
    from public.sites s where s.id = p_site), false);
$$;

-- Platform admins confirm, after checking ownership, that a site may use the shared Google account.
create or replace function public.set_gsc_allowed(p_site uuid, p_allowed boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare s public.sites;
begin
  if not private.is_platform_admin() then raise exception 'not allowed'; end if;
  select * into s from public.sites where id = p_site;
  if s.id is null then raise exception 'site not found'; end if;
  if p_allowed and exists (select 1 from public.sites o where o.org_id <> s.org_id and private.site_host(o.url) = private.site_host(s.url)) then
    raise exception 'this domain is also registered in another agency: confirm ownership before allowing it'; end if;
  update public.sites set gsc_allowed = p_allowed, gsc_allowed_by = case when p_allowed then (select auth.uid()) end, gsc_allowed_at = case when p_allowed then now() end where id = p_site;
  insert into public.audit_log (org_id, site_id, actor, action, target) values (s.org_id, s.id, (select auth.uid()), case when p_allowed then 'gsc.allow' else 'gsc.revoke' end, s.id::text);
  return jsonb_build_object('site', s.id, 'allowed', p_allowed);
end;
$$;

create or replace function public.create_job(p_site uuid, p_kind text, p_title text, p_source text default 'agency', p_risk text default 'low',
  p_requires_approval boolean default false, p_priority int default 3, p_inputs jsonb default '{}', p_idempotency_key text default null,
  p_objective text default null, p_depends_on uuid[] default '{}', p_budget_usd numeric default 0)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs; v_org uuid := private.site_org(p_site); is_service boolean := (select auth.role()) = 'service_role';
  v_budget numeric := greatest(coalesce(p_budget_usd, 0), 0);
begin
  if v_org is null then raise exception 'site not found'; end if;
  if not is_service and not private.is_member(v_org) then raise exception 'not allowed'; end if;
  if not is_service and p_source not in ('agency', 'on_demand') then raise exception 'agency staff create agency or on-demand jobs'; end if;
  if not is_service then
    if v_budget > 5 then raise exception 'a job created by agency staff can carry at most $5'; end if;
    if (select count(*) from public.jobs where org_id = v_org and created_by = (select auth.uid()) and created_at > now() - interval '1 day') >= 100 then
      raise exception 'at most 100 jobs a day per person'; end if;
  end if;
  if p_idempotency_key is not null then
    select * into j from public.jobs where site_id = p_site and idempotency_key = p_idempotency_key;
    if j.id is not null then return j; end if; -- a repeated event does not create a second job
  end if;
  insert into public.jobs (org_id, site_id, kind, title, objective, source, priority, risk, requires_approval, inputs, idempotency_key, depends_on, budget_usd, created_by)
    values (v_org, p_site, p_kind, p_title, p_objective, p_source, least(greatest(coalesce(p_priority, 3), 1), 5), p_risk,
            p_requires_approval or p_risk = 'high' or p_source = 'client_submission' or (not is_service and v_budget > 0),
            coalesce(p_inputs, '{}'), p_idempotency_key, coalesce(p_depends_on, '{}'), v_budget, (select auth.uid()))
    returning * into j;
  insert into public.job_events (job_id, org_id, actor_kind, actor, to_status, note) values (j.id, j.org_id, case when is_service then 'agent' else 'user' end, coalesce((select auth.uid())::text, 'service'), 'proposed', 'created');
  insert into public.audit_log (org_id, site_id, actor, action, target) values (j.org_id, j.site_id, (select auth.uid()), 'job.create', j.id::text);
  return j;
end;
$$;

revoke all on function private.site_host(text), private.sites_gsc_reset(), public.gsc_allowed(uuid), public.set_gsc_allowed(uuid, boolean) from public, anon, authenticated;
grant execute on function public.gsc_allowed(uuid) to service_role;
grant execute on function public.set_gsc_allowed(uuid, boolean) to authenticated;
grant execute on function private.site_host(text) to service_role, authenticated;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108080000', 'security_fixes');

-- ===== 20261108090000_strategy_draft.sql =====
-- D35 (owner review D1, 2026-11-08): the strategy draft is made at once and the agency adopts it with one approval.
-- Drafting needs no approval to start, so the old rule "a worker cannot authorize gated work" no longer covers it:
-- anything waiting for the agency (awaiting_approval) is now decided only by the agency, gated or not.
-- Not applied anywhere.
create or replace function public.transition_job(p_job uuid, p_to text, p_actor text, p_note text default null, p_data jsonb default null)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs;
begin
  select * into j from public.jobs where id = p_job;
  -- Rejecting, authorizing gated work, and deciding anything that waits for the agency belong to the agency (approve_job).
  if p_to = 'rejected' or (p_to = 'authorized' and (j.requires_approval or j.status = 'awaiting_approval')) then
    raise exception 'only an agency approval can authorize or reject';
  end if;
  return private.move_job(p_job, p_to, 'agent', p_actor, p_note, p_data);
end;
$$;
revoke all on function public.transition_job(uuid, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.transition_job(uuid, text, text, text, jsonb) to service_role;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108090000', 'strategy_draft');

-- ===== 20261108100000_invite_only.sql =====
-- Invite-only sign-up until public launch (owner decision Q8, 2026-11-08).
-- Turning off sign-ups in Supabase Auth would also stop invited people from creating their account, because both the
-- agency invite (public.invites) and the client invite (public.client_invites) expect the person to sign up with the
-- invited email. So the gate is here instead: a new account is refused unless its email has a pending invite. Existing
-- users and their sign-in are untouched. A platform admin (or the service role) can open sign-up at launch.

create table if not exists private.platform_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now(),
  updated_by uuid
);
alter table private.platform_settings enable row level security; -- no policies: only the functions below read or write it
revoke all on private.platform_settings from public, anon, authenticated;
insert into private.platform_settings (key, value) values ('invite_only', 'true') on conflict (key) do nothing;

create or replace function private.invite_only() returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select value = 'true'::jsonb from private.platform_settings where key = 'invite_only'), true);
$$;

-- Runs before the after-insert triggers that create a workspace or accept invites.
create or replace function private.gate_signup() returns trigger language plpgsql security definer set search_path = '' as $$
declare v_email text := lower(trim(coalesce(new.email, '')));
begin
  if not private.invite_only() then return new; end if;
  if v_email <> '' and (exists (select 1 from public.invites i where i.email = v_email and i.accepted_at is null)
      or exists (select 1 from public.client_invites i where i.email = v_email and i.accepted_at is null)) then
    return new;
  end if;
  raise exception 'sign-up is by invitation only' using errcode = 'P0001';
end $$;
revoke all on function private.gate_signup() from public, anon, authenticated;
revoke all on function private.invite_only() from public, anon, authenticated;

drop trigger if exists on_auth_user_gate_signup on auth.users;
create trigger on_auth_user_gate_signup before insert on auth.users for each row execute function private.gate_signup();

-- Platform admins open or close sign-up; who changed it and when stays on the setting (audit_log is per agency).
create or replace function public.set_invite_only(p_on boolean) returns jsonb language plpgsql security definer set search_path = '' as $$
begin
  if p_on is null then raise exception 'invite_only must be true or false'; end if;
  if not (private.is_platform_admin() or (select auth.role()) = 'service_role') then raise exception 'not allowed'; end if;
  insert into private.platform_settings (key, value, updated_at, updated_by) values ('invite_only', to_jsonb(p_on), now(), (select auth.uid()))
    on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at, updated_by = excluded.updated_by;
  return jsonb_build_object('invite_only', p_on);
end $$;
revoke all on function public.set_invite_only(boolean) from public, anon;
grant execute on function public.set_invite_only(boolean) to authenticated, service_role;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108100000', 'invite_only');

-- ===== 20261108110000_github_execution.sql =====
-- Verified execution through the site's own GitHub repository (R1-E1, decision D37).
-- The hosted SEO God never edits a website itself. For a site whose code is in GitHub, an approved recommendation
-- becomes an issue in that repository, and the site's existing seo-implement workflow drafts a pull request (content
-- files only, no builds, seo-check and seo-review on the pull request, merged by a person or the site's own autopilot
-- policy, D17). The scheduler then follows the pull request and verifies the change with the next scan.
--
-- The agency brings its own GitHub token (rule 6): a fine-grained token for that one repository with Issues and Actions
-- read/write and Pull requests and Metadata read. It is stored in Supabase Vault, is never returned to any browser,
-- and only the service role (the Worker) can read it, for a connected site.

-- Agency owners connect or disconnect GitHub for one of their sites.
create or replace function public.connect_github(p_site uuid, p_repo text, p_token text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.site_org(p_site); v_repo text := trim(coalesce(p_repo, '')); v_name text := 'github_token:' || p_site::text; v_id uuid;
begin
  if v_org is null or not private.is_owner(v_org) then raise exception 'only an owner of the agency can connect GitHub'; end if;
  if v_repo !~ '^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$' or v_repo ~ '(^|/)\.+(/|$)' then raise exception 'repository must look like owner/name'; end if;
  if p_token is null or length(trim(p_token)) < 20 or trim(p_token) ~ '\s' then raise exception 'that does not look like a GitHub token'; end if;
  select id into v_id from vault.secrets where name = v_name;
  if v_id is null then perform vault.create_secret(trim(p_token), v_name, 'GitHub token for one site (SEO Autopilot)');
  else perform vault.update_secret(v_id, trim(p_token)); end if;
  update public.sites set repo = v_repo where id = p_site;
  insert into public.integrations (org_id, site_id, provider, scope, status, detail, last_error)
    values (v_org, p_site, 'github', 'write', 'connected', jsonb_build_object('repo', v_repo, 'connectedAt', now()), null)
    on conflict (site_id, provider, scope) do update set status = 'connected', detail = excluded.detail, last_error = null;
  insert into public.audit_log (org_id, site_id, actor, action, target, data) values (v_org, p_site, (select auth.uid()), 'integration.connect', 'github', jsonb_build_object('repo', v_repo));
  return jsonb_build_object('provider', 'github', 'repo', v_repo, 'status', 'connected');
end $$;

create or replace function public.disconnect_github(p_site uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid := private.site_org(p_site);
begin
  if v_org is null or not private.is_owner(v_org) then raise exception 'only an owner of the agency can disconnect GitHub'; end if;
  delete from vault.secrets where name = 'github_token:' || p_site::text;
  update public.integrations set status = 'revoked', last_error = null where site_id = p_site and provider = 'github' and scope = 'write';
  insert into public.audit_log (org_id, site_id, actor, action, target) values (v_org, p_site, (select auth.uid()), 'integration.disconnect', 'github');
  return jsonb_build_object('provider', 'github', 'status', 'revoked');
end $$;

-- What agency members may see about a site's integrations: never a secret.
create or replace function public.site_integrations(p_site uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_org uuid := private.site_org(p_site);
begin
  if v_org is null or not private.is_member(v_org) then raise exception 'not allowed'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('provider', i.provider, 'scope', i.scope, 'status', i.status, 'repo', i.detail->>'repo',
           'lastOkAt', i.last_ok_at, 'lastError', i.last_error) order by i.provider, i.scope)
         from public.integrations i where i.site_id = p_site), '[]'::jsonb);
end $$;

-- Changes on their way to the website, for agency members: the issue, the pull request, the verification. No secrets.
create or replace function public.site_deployments(p_site uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_org uuid := private.site_org(p_site);
begin
  if v_org is null or not private.is_member(v_org) then raise exception 'not allowed'; end if;
  return coalesce((select jsonb_agg(x order by x->>'updatedAt' desc) from (
    select jsonb_build_object('id', j.id, 'title', j.title, 'status', j.status, 'updatedAt', j.updated_at,
             'page', j.outputs->'deploy'->>'url', 'issue', j.outputs->'deploy'->'issue', 'issueUrl', j.outputs->'deploy'->>'issueUrl',
             'pr', j.outputs->'deploy'->'pr', 'prUrl', j.outputs->'deploy'->>'prUrl', 'mergedAt', j.outputs->'deploy'->>'mergedAt',
             'verification', j.outputs->'verification'->>'summary', 'error', j.error) x
      from public.jobs j where j.site_id = p_site and j.kind = 'implement' order by j.updated_at desc limit 20) t), '[]'::jsonb);
end $$;

-- The Worker's view: the repository and token of a connected site, or nothing.
create or replace function public.github_target(p_site uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('repo', i.detail->>'repo', 'token', s.decrypted_secret)
    from public.integrations i join vault.decrypted_secrets s on s.name = 'github_token:' || p_site::text
   where i.site_id = p_site and i.provider = 'github' and i.scope = 'write' and i.status = 'connected' and i.detail ? 'repo';
$$;

-- The Worker reports whether a call worked, so the agency sees a broken token instead of silence.
create or replace function public.record_integration_status(p_site uuid, p_provider text, p_ok boolean, p_error text default null)
returns void language sql security definer set search_path = '' as $$
  update public.integrations set last_ok_at = case when p_ok then now() else last_ok_at end,
         last_error = case when p_ok then null else left(p_error, 300) end,
         status = case when p_ok then 'connected' when status = 'connected' then 'error' else status end
   where site_id = p_site and provider = p_provider and status in ('connected', 'error');
$$;

-- An agency member asks for one recommendation of an accepted advice result to be implemented. This only drafts the
-- work order (free, no change anywhere); the agency approves the exact work order before anything reaches GitHub.
create or replace function public.request_implementation(p_job uuid, p_index int)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare src public.jobs; rec jsonb; j public.jobs;
begin
  select * into src from public.jobs where id = p_job;
  if src.id is null or not private.is_member(src.org_id) then raise exception 'not allowed'; end if;
  if src.status <> 'completed' then raise exception 'only accepted advice can be implemented'; end if;
  rec := src.outputs->'proposal'->'recommendations'->p_index;
  if rec is null or jsonb_typeof(rec) <> 'object' then raise exception 'no such recommendation'; end if;
  if not exists (select 1 from public.integrations i where i.site_id = src.site_id and i.provider = 'github' and i.scope = 'write' and i.status = 'connected') then
    raise exception 'connect GitHub for this website first';
  end if;
  j := public.create_job(src.site_id, 'implement', left('Implement: ' || coalesce(rec->>'title', 'recommendation'), 200), 'agency', 'medium', false, 2,
         jsonb_build_object('sourceJob', src.id, 'index', p_index, 'recommendation', rec), 'implement:' || src.id::text || ':' || p_index::text, 'implement an accepted recommendation through the site''s GitHub workflow');
  return j;
end $$;

revoke all on function public.connect_github(uuid, text, text), public.disconnect_github(uuid), public.site_integrations(uuid), public.github_target(uuid),
  public.record_integration_status(uuid, text, boolean, text), public.request_implementation(uuid, int), public.site_deployments(uuid) from public, anon, authenticated;
grant execute on function public.connect_github(uuid, text, text), public.disconnect_github(uuid), public.site_integrations(uuid), public.request_implementation(uuid, int), public.site_deployments(uuid) to authenticated;
grant execute on function public.github_target(uuid), public.record_integration_status(uuid, text, boolean, text) to service_role;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108110000', 'github_execution');

-- ===== 20261108120000_notifications_reports.sql =====
-- Notifications and the monthly work report (decision D38).
-- Notifications are derived live from what is waiting, so they can never disagree with the work itself; the only state
-- kept is when each person last looked. No email provider is involved (REVIEW-QUESTIONS Q7 is still open): the portal
-- shows them. The work report tells an agency and its client what was done for one website in one month, without
-- internal details (no costs, agents, prompts, reviews or private analysis).

create table public.notification_seen (
  user_id uuid primary key references auth.users (id) on delete cascade,
  seen_at timestamptz not null default now()
);
alter table public.notification_seen enable row level security; -- no policies: only the functions below use it
revoke all on public.notification_seen from public, anon, authenticated;

-- The items for one person, computed from the work itself. Used by the portal (for the signed-in person) and by the
-- email digest (for each person, by the service role only).
create or replace function private.notifications_for(p_uid uuid)
returns table (kind text, site uuid, site_name text, title text, at timestamptz, page text)
language sql stable security definer set search_path = '' as $$
  with mine as (select s.id, s.name from public.sites s join public.org_members om on om.org_id = s.org_id and om.user_id = p_uid)
  -- Agency: decisions waiting, work that needs a person, client requests, changes verified or stopped, broken integrations, planning errors.
  select 'approval', j.site_id, m.name, j.title, j.updated_at, 'god' from public.jobs j join mine m on m.id = j.site_id where j.status = 'awaiting_approval'
  union all select 'stuck', j.site_id, m.name, j.title || coalesce(': ' || left(j.error, 120), ''), j.updated_at, 'god' from public.jobs j join mine m on m.id = j.site_id where j.status = 'escalated'
  union all select 'request', x.site_id, m.name, x.title, x.created_at, 'requests' from public.submissions x join mine m on m.id = x.site_id where x.status in ('received', 'needs_clarification')
  union all select case when j.status = 'completed' then 'verified' else 'change_failed' end, j.site_id, m.name, coalesce(j.outputs->'verification'->>'summary', j.title), j.updated_at, 'god'
    from public.jobs j join mine m on m.id = j.site_id where j.kind = 'implement' and j.status in ('completed', 'escalated') and j.updated_at > now() - interval '14 days'
  union all select 'integration', i.site_id, m.name, i.provider || ': ' || coalesce(i.last_error, 'not working'), coalesce(i.last_ok_at, i.created_at), 'god'
    from public.integrations i join mine m on m.id = i.site_id where i.status = 'error'
  union all select 'planning', t.site_id, m.name, 'Planning stopped: ' || left(t.outcome->>'error', 160), t.ticked_at, 'god'
    from public.god_site_ticks t join mine m on m.id = t.site_id where t.outcome->>'error' is not null
  -- Clients: the agency answered one of their own requests (still a viewer of that site).
  union all select 'answer', x.site_id, s.name, x.title || ' · ' || replace(x.status, '_', ' '), x.decided_at, 'requests'
    from public.submissions x join public.sites s on s.id = x.site_id
   where x.submitted_by = p_uid and x.decided_at is not null and x.decided_at > now() - interval '30 days'
     and exists (select 1 from public.client_members cm where cm.client_id = s.client_id and cm.user_id = p_uid);
$$;
revoke all on function private.notifications_for(uuid) from public, anon, authenticated;

create or replace function public.my_notifications()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_uid uuid := (select auth.uid()); v_seen timestamptz;
begin
  if v_uid is null then raise exception 'not allowed'; end if;
  select n.seen_at into v_seen from public.notification_seen n where n.user_id = v_uid;
  return (
    with items as (select * from private.notifications_for(v_uid))
    select jsonb_build_object('seenAt', v_seen,
      'unread', (select count(*) from items where at > coalesce(v_seen, '-infinity'::timestamptz)),
      'items', coalesce((select jsonb_agg(jsonb_build_object('kind', kind, 'site', site, 'siteName', site_name, 'title', left(title, 300), 'at', at, 'page', page,
                 'unread', at > coalesce(v_seen, '-infinity'::timestamptz)) order by at desc) from (select * from items order by at desc limit 50) t), '[]'::jsonb)));
end $$;

create or replace function public.mark_notifications_seen()
returns timestamptz language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := (select auth.uid()); v_at timestamptz := now();
begin
  if v_uid is null then raise exception 'not allowed'; end if;
  insert into public.notification_seen (user_id, seen_at) values (v_uid, v_at) on conflict (user_id) do update set seen_at = excluded.seen_at;
  return v_at;
end $$;

-- What was done for one website in one month: for the agency and for that website's client accounts. Only outcomes:
-- advice accepted, changes merged and verified, client requests answered, and the audit at the start and end of the month.
create or replace function public.site_work_report(p_site uuid, p_month date default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_from timestamptz := date_trunc('month', coalesce(p_month, now()::date)::timestamptz); v_to timestamptz;
begin
  if not (private.is_member(private.site_org(p_site)) or private.is_client_viewer(p_site)) then raise exception 'not allowed'; end if;
  v_to := v_from + interval '1 month';
  return jsonb_build_object(
    'site', (select jsonb_build_object('name', s.name, 'url', s.url) from public.sites s where s.id = p_site),
    'brand', (select jsonb_build_object('name', coalesce(o.brand_name, o.name), 'color', o.brand_color) from public.sites s join public.orgs o on o.id = s.org_id where s.id = p_site),
    'month', to_char(v_from, 'YYYY-MM'),
    'strategy', (select jsonb_build_object('approved', m.value->>'status' = 'approved', 'objective', m.value->>'objective', 'since', m.created_at)
                   from public.site_memory m where m.site_id = p_site and m.kind = 'strategy' and m.key = 'initial' and m.superseded_at is null limit 1),
    'advice', coalesce((select jsonb_agg(jsonb_build_object('title', j.title, 'at', j.updated_at,
                  'recommendations', (select coalesce(jsonb_agg(jsonb_build_object('title', r->>'title', 'url', r->>'url')), '[]'::jsonb) from jsonb_array_elements(coalesce(j.outputs->'proposal'->'recommendations', '[]'::jsonb)) r))
                  order by j.updated_at)
                from public.jobs j where j.site_id = p_site and j.status = 'completed' and j.kind like 'agent:%' and j.updated_at >= v_from and j.updated_at < v_to), '[]'::jsonb),
    'changes', coalesce((select jsonb_agg(jsonb_build_object('title', j.title, 'status', j.status, 'page', j.outputs->'deploy'->>'url', 'mergedAt', j.outputs->'deploy'->>'mergedAt',
                  'verification', j.outputs->'verification'->>'summary') order by j.updated_at)
                from public.jobs j where j.site_id = p_site and j.kind = 'implement' and j.status in ('completed', 'verifying', 'deploying', 'escalated') and j.updated_at >= v_from and j.updated_at < v_to), '[]'::jsonb),
    'requests', coalesce((select jsonb_agg(jsonb_build_object('title', x.title, 'status', x.status, 'note', x.agency_note, 'at', x.decided_at) order by x.decided_at)
                from public.submissions x where x.site_id = p_site and x.decided_at >= v_from and x.decided_at < v_to), '[]'::jsonb),
    'audit', (select jsonb_build_object('generatedAt', m.value->>'generatedAt', 'pages', m.value->'summary'->'pagesCrawled', 'bySeverity', m.value->'summary'->'bySeverity')
                from public.site_memory m where m.site_id = p_site and m.kind = 'report' and m.key = 'audit' and m.created_at < v_to order by m.created_at desc limit 1),
    'auditBefore', (select jsonb_build_object('generatedAt', m.value->>'generatedAt', 'pages', m.value->'summary'->'pagesCrawled', 'bySeverity', m.value->'summary'->'bySeverity')
                from public.site_memory m where m.site_id = p_site and m.kind = 'report' and m.key = 'audit' and m.created_at < v_from order by m.created_at desc limit 1));
end $$;

-- The workforce for one site (agency only): what each kind of work did in the last days, so the agency can see which
-- departments and specialists worked on the site and with what result.
create or replace function public.site_workforce(p_site uuid, p_days int default 30)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_member(private.site_org(p_site)) then raise exception 'not allowed'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('kind', kind, 'total', total, 'completed', completed, 'waiting', waiting, 'active', active, 'stopped', stopped, 'lastAt', last_at) order by last_at desc)
    from (select j.kind, count(*) total, count(*) filter (where j.status = 'completed') completed, count(*) filter (where j.status = 'awaiting_approval') waiting,
                 count(*) filter (where j.status in ('scoped', 'queued', 'running', 'awaiting_review', 'authorized', 'deploying', 'verifying')) active,
                 count(*) filter (where j.status in ('failed', 'escalated', 'rejected', 'cancelled')) stopped, max(j.updated_at) last_at
            from public.jobs j where j.site_id = p_site and j.updated_at > now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 365)) group by j.kind) t), '[]'::jsonb);
end $$;

revoke all on function public.my_notifications(), public.mark_notifications_seen(), public.site_work_report(uuid, date), public.site_workforce(uuid, int) from public, anon, authenticated;
grant execute on function public.my_notifications(), public.mark_notifications_seen(), public.site_work_report(uuid, date), public.site_workforce(uuid, int) to authenticated;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108120000', 'notifications_reports');

-- ===== 20261108130000_email.sql =====
-- Email through Supabase's own SMTP (decision D40).
-- Invitations: the notify Edge Function asks Supabase Auth to invite each new invitee, so the email goes out through the
-- project's Auth SMTP and template (Dashboard -> Authentication -> SMTP / Email templates). The invite-only gate (D36)
-- lets the account be created because the invite is pending; existing triggers then join the agency or the client.
-- Daily summaries: the same function sends one email per person with notifications they have not seen, through the
-- SMTP server whose details are kept as Edge Function secrets (SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, SMTP_FROM).
-- People can turn the summary off. Nothing here sends anything by itself: the Cloudflare scheduler calls the function.

alter table public.invites add column if not exists emailed_at timestamptz;
alter table public.client_invites add column if not exists emailed_at timestamptz;

create table public.email_prefs (
  user_id uuid primary key references auth.users (id) on delete cascade,
  daily_summary boolean not null default true,
  last_summary_at timestamptz
);
alter table public.email_prefs enable row level security; -- no policies: only the functions below use it
revoke all on public.email_prefs from public, anon, authenticated;

-- Each person decides whether they get the daily summary.
create or replace function public.set_email_summary(p_on boolean)
returns boolean language plpgsql security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null then raise exception 'not allowed'; end if;
  if p_on is null then raise exception 'choose on or off'; end if;
  insert into public.email_prefs (user_id, daily_summary) values ((select auth.uid()), p_on)
    on conflict (user_id) do update set daily_summary = excluded.daily_summary;
  return p_on;
end $$;

create or replace function public.my_email_summary()
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select daily_summary from public.email_prefs where user_id = (select auth.uid())), true);
$$;

-- The service's work list: invitations not yet emailed (last 7 days, still pending, no account yet) and people due a
-- summary (unseen items since they last looked or were last emailed, at most one email a day, summary switched on).
create or replace function public.email_queue(p_limit int default 50)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'invites', coalesce((select jsonb_agg(x) from (
        select 'agency' kind, i.org_id::text || ':' || i.email id, i.email, coalesce(o.brand_name, o.name) agency, i.created_at from public.invites i join public.orgs o on o.id = i.org_id
         where i.accepted_at is null and i.emailed_at is null and i.created_at > now() - interval '7 days' and not exists (select 1 from auth.users u where lower(u.email) = i.email)
        union all
        select 'client', ci.id::text, ci.email, coalesce(o.brand_name, o.name), ci.created_at from public.client_invites ci join public.clients c on c.id = ci.client_id join public.orgs o on o.id = c.org_id
         where ci.accepted_at is null and ci.emailed_at is null and ci.created_at > now() - interval '7 days' and not exists (select 1 from auth.users u where lower(u.email) = ci.email)
        order by 5 limit greatest(least(coalesce(p_limit, 50), 200), 1)) x), '[]'::jsonb),
    'summaries', coalesce((select jsonb_agg(y) from (
        select u.id user_id, u.email, (select jsonb_agg(jsonb_build_object('kind', n.kind, 'siteName', n.site_name, 'title', left(n.title, 300), 'at', n.at, 'site', n.site, 'page', n.page) order by n.at desc)
                 from (select * from private.notifications_for(u.id) f where f.at > greatest(coalesce(ns.seen_at, '-infinity'::timestamptz), coalesce(ep.last_summary_at, '-infinity'::timestamptz)) order by f.at desc limit 20) n) items
          from auth.users u left join public.notification_seen ns on ns.user_id = u.id left join public.email_prefs ep on ep.user_id = u.id
         where u.email is not null and coalesce(ep.daily_summary, true) and coalesce(ep.last_summary_at, '-infinity'::timestamptz) < now() - interval '20 hours'
           and exists (select 1 from private.notifications_for(u.id) f where f.at > greatest(coalesce(ns.seen_at, '-infinity'::timestamptz), coalesce(ep.last_summary_at, '-infinity'::timestamptz)))
         limit greatest(least(coalesce(p_limit, 50), 200), 1)) y), '[]'::jsonb));
$$;

-- The service records what it sent, so nothing is emailed twice.
create or replace function public.email_sent(p_kind text, p_id text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if p_kind = 'agency' then update public.invites set emailed_at = now() where org_id = split_part(p_id, ':', 1)::uuid and email = substr(p_id, position(':' in p_id) + 1);
  elsif p_kind = 'client' then update public.client_invites set emailed_at = now() where id = p_id::bigint;
  elsif p_kind = 'summary' then insert into public.email_prefs (user_id, last_summary_at) values (p_id::uuid, now())
    on conflict (user_id) do update set last_summary_at = excluded.last_summary_at;
  else raise exception 'unknown kind'; end if;
end $$;

-- The Worker reads the shared scan secret from Vault instead of holding a copy (service role only).
create or replace function public.scan_secret()
returns text language sql stable security definer set search_path = '' as $$
  select decrypted_secret from vault.decrypted_secrets where name = 'scan_secret';
$$;

revoke all on function public.set_email_summary(boolean), public.my_email_summary(), public.email_queue(int), public.email_sent(text, text), public.scan_secret() from public, anon, authenticated;
grant execute on function public.set_email_summary(boolean), public.my_email_summary() to authenticated;
grant execute on function public.email_queue(int), public.email_sent(text, text), public.scan_secret() to service_role;

insert into supabase_migrations.schema_migrations (version, name) values ('20261108130000', 'email');

