select vault.create_secret('https://ymwwwhdlyjnqbxxhtcew.supabase.co/functions/v1/scan', 'scan_url') where not exists (select 1 from vault.secrets where name = 'scan_url');
select vault.create_secret(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 'scan_secret') where not exists (select 1 from vault.secrets where name = 'scan_secret');
